def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        q.append((a, b))
            components.append((color, cells))

    # Find the largest non-background component that is a two-sided L.
    markers = []
    for i, (color, cells) in enumerate(components):
        if color == bg:
            continue
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        shapes = [
            ({(r0, c) for c in range(c0, c1 + 1)} | {(r, c0) for r in range(r0, r1 + 1)}, r0, c0, -1, -1),
            ({(r0, c) for c in range(c0, c1 + 1)} | {(r, c1) for r in range(r0, r1 + 1)}, r0, c1, -1, 1),
            ({(r1, c) for c in range(c0, c1 + 1)} | {(r, c0) for r in range(r0, r1 + 1)}, r1, c0, 1, -1),
            ({(r1, c) for c in range(c0, c1 + 1)} | {(r, c1) for r in range(r0, r1 + 1)}, r1, c1, 1, 1),
        ]
        for shape, er, ec, dr, dc in shapes:
            if set(cells) == shape and len(cells) >= 5:
                markers.append((len(cells), i, color, er, ec, dr, dc))
                break
    if not markers:
        return [row[:] for row in grid]

    _, marker_i, marker_color, er, ec, dr, dc = max(markers)
    targets = []
    for i, (color, cells) in enumerate(components):
        if i == marker_i or color == bg:
            continue
        cr = sum(r for r, c in cells) / len(cells)
        cc = sum(c for r, c in cells) / len(cells)
        if (cr - er) * dr > 0 and (cc - ec) * dc > 0:
            dist = min(abs(r - er) + abs(c - ec) for r, c in cells)
            targets.append((dist, -len(cells), i))
    if not targets:
        return [row[:] for row in grid]

    _, _, target_i = min(targets)
    out = [row[:] for row in grid]
    for r, c in components[target_i][1]:
        out[r][c] = marker_color
    return out


